import java.util.ArrayList;
import java.util.Collections;

public class Registro {
    private ArrayList<Integracion> integraciones;
    public Registro() {
        integraciones = new ArrayList<Integracion>();
    }


    // Registro de una Integracion cualquiera

    public boolean registrarIntegracion(Integracion integracion) {

        // Comprueba que exista
        if (integracion == null) {
            return false;
        }

        // Comprueba que tenga id
        if (integracion.getId() == null) {
            return false;
        }

		//Comprueba que no esté vacío
        if (integracion.getId().isEmpty()) {
            return false;
        }

        // Id distinto
        if (buscarIntegracion(integracion.getId()) != null) {
            return false;
        }

        // Si cumplió TOOODO, ahora sí agregalo
        integraciones.add(integracion);
        return true;
    }


    // Busar integración por Id

    public Integracion buscarIntegracion(String id) {
        for (Integracion integracion : integraciones) {
            if (integracion.getId().equals(id)) {
                return integracion;
            }
        }

        return null;
    }


    // Mostrar Integraciones
    public void mostrarIntegraciones() {
        System.out.println("\nIntegraciones\n");
        boolean encontradas = false;

        for (Integracion integracion : integraciones) {
            if (integracion.getListo()) {
                System.out.println(integracion);
                System.out.println();
                encontradas = true;
            }
        }

        if (!encontradas) {
            System.out.println("No hay integraciones activas.");
        }
    }


    // Muestre configuración con id

    public void mostrarConfiguracion(String id) {
        Integracion integracion = buscarIntegracion(id);
        if (integracion == null) {
            System.out.println("No se encontro la integracion solicitada.");
            return;
        }

        System.out.println("\nConfiguración\n");

        System.out.println("Id: " + integracion.getId());
        System.out.println("Nombre: " + integracion.getNombre());
        System.out.println("Latencia: " + integracion.getLatencia() + " ms");
        System.out.println("Configuracion: " + integracion.getConfiguracion());

        // Según el boolean
        if (integracion.getListo()) {
            System.out.println("Estado: Conectado");
        }
        else {
            System.out.println("Estado: Desconectado");
        }
    }


    // El orden con el CompareTo
    public void ordenarIntegraciones() {
        // Ordena utilizando el compareTo() de Integracion.
        Collections.sort(integraciones);

        System.out.println("\nCatálogo Ordenado\n");

        for (Integracion integracion : integraciones) {
            System.out.println(integracion);
            System.out.println();
        }
    }
}
